145	std::vector<ProjectEntry> OrcaHomeBackend::recent_projects() const
146	{
147	    // Which project each printing machine is running, so a card can say so.
148	    // This is the only per-project status the codebase can answer today; the
149	    // rest is the file's own modified time until a project-state store exists.
150	    std::map<std::string, std::string> printing_by_stem;
151	    if (DeviceManager* devices = wxGetApp().getDeviceManager()) {
152	        for (const auto& entry : devices->get_my_machine_list()) {
153	            MachineObject* machine = entry.second;
154	            if (machine == nullptr)
155	                continue;
156	            if (machine_is_printing(*machine) && !machine->subtask_name.empty())
157	                printing_by_stem.emplace(machine->subtask_name, machine->get_dev_name());
158	        }
159	    }
160	
161	    std::vector<ProjectEntry>    projects;
162	    boost::property_tree::wptree recent;
163	    m_frame.get_recent_projects(recent, kThumbnailCap);
164	    size_t index = 0;
165	    for (const auto& node : recent) {
166	        const auto&  item = node.second;
167	        ProjectEntry project;
168	        project.id              = std::to_string(index++);
169	        const std::wstring path = item.get<std::wstring>(L"path", L"");
170	        project.name            = file_stem(path);
171	        project.path            = utf8(path);
172	        project.thumbnail_url   = utf8(item.get<std::wstring>(L"image", L""));
173	
174	        const auto printing = printing_by_stem.find(file_stem(path));
175	        if (printing != printing_by_stem.end()) {
176	            project.status_kind = ProjectStatusKind::Printing;
177	            project.status_text = std::string(
178	                wxString::Format(_L("Printing on %s"), wxString::FromUTF8(printing->second)).ToUTF8());
179	        } else {
180	            // Honest about what is known: nothing records whether this project
181	            // is sliced, so the card shows when it was last written, and says
182	            // which fact it is showing rather than dropping a bare timestamp
183	            // where the design puts a state.
184	            project.status_kind = ProjectStatusKind::Unknown;
185	            // The recent list stamps "YYYY-MM-DD HH:MM:SS"; a status line does
186	            // not need the second.
187	            wxString when = wxString(item.get<std::wstring>(L"time", L""));
188	            if (when.length() == 19 && when[16] == ':')
189	                when = when.Left(16);
190	            if (!when.empty())
191	                project.status_text = std::string(wxString::Format(_L("Edited %s"), when).ToUTF8());
192	        }
193	        projects.push_back(std::move(project));
194	    }
195	    return projects;
196	}
