237	        // Spools are remembered per printer; the material the project has
238	        // loaded only describes the one in force.
239	        if (m_spools != nullptr)
240	            for (const Workspace::Spool& spool : m_spools->spools_for(named.name))
241	                printer.spools.push_back(SpoolEntry{spool.colour});
242	        if (named.selected && !printer.spools.empty())
243	            printer.material_label = material;
244	        printers.push_back(std::move(printer));
245	    }
246	
247	    // Devices no named printer stands for. Their name and binding are the
248	    // device's, so renaming and removing them are upstream's device dialogs,
249	    // offered where upstream's device list offers them.
250	    for (const auto& [id, machine] : machines) {
251	        if (represented.count(id) > 0)
252	            continue;
253	        PrinterEntry printer;
254	        printer.id         = kDevicePrefix + id;
255	        printer.name       = machine->get_dev_name();
256	        printer.kind       = PrinterKind::Device;
257	        printer.can_rename = !machine->is_lan_mode_printer() && machine->is_online();
258	        printer.can_remove = !machine->is_lan_mode_printer();
259	        describe_device(*machine, printer);
260	        printers.push_back(std::move(printer));
261	    }
262	    return printers;
263	}
264	
265	void OrcaHomeBackend::open_project(const std::string& project_id)
266	{
267	    if (project_id.empty())
268	        return;
269	    const size_t                 wanted = static_cast<size_t>(std::stoul(project_id));
270	    boost::property_tree::wptree recent;
271	    m_frame.get_recent_projects(recent, 0);
272	    size_t at = 0;
273	    for (const auto& node : recent) {
274	        if (at++ != wanted)
275	            continue;
276	        const wxString path(node.second.get<std::wstring>(L"path", L""));
277	        m_frame.open_recent_project(wanted, path);
278	        // Opening a project is a move to the workspace, but only if it opens.
279	        // open_recent_project queues the load behind can_load_project(), which
280	        // asks about unsaved changes and abandons the load when the answer is
281	        // Cancel. Queueing the move behind that lambda -- CallAfter is FIFO --
282	        // and confirming the project that is now open is the one that was
283	        // asked for keeps a cancelled open on Home instead of navigating out
284	        // from under it.
285	        m_frame.CallAfter([this, path] {
286	            Plater* plater = wxGetApp().plater();
287	            if (plater != nullptr && wxFileName(plater->get_project_filename()).SameAs(wxFileName(path)))
288	                m_frame.select_tab(size_t(MainFrame::tp3DEditor));
289	        });
290	        return;
291	    }
292	}
293	
294	void OrcaHomeBackend::new_project()
295	{
296	    Plater* plater = wxGetApp().plater();
297	    if (plater == nullptr)
298	        return;
299	    // Cancelling the unsaved-changes question leaves the old project in place,
300	    // so it leaves Home in place too.
301	    if (plater->new_project() != wxID_CANCEL)
302	        m_frame.select_tab(size_t(MainFrame::tp3DEditor));
303	}
304	
305	void OrcaHomeBackend::import_model()
306	{
307	    Plater* plater = wxGetApp().plater();
308	    if (plater == nullptr)
309	        return;
310	    // add_model imports into the project that is open and runs its own modal
311	    // file dialog. It returns void, so the object count before and after is
312	    // what says whether anything arrived: cancelling the dialog leaves Home
313	    // where it was, as cancelling New does.
314	    const size_t before = plater->model().objects.size();
315	    plater->add_model();
316	    if (plater->model().objects.size() != before)
317	        m_frame.select_tab(size_t(MainFrame::tp3DEditor));
318	}
