320	void OrcaHomeBackend::launch_monitor(const std::string& printer_id)
321	{
322	    // A named printer is monitored through the device it stands for.
323	    std::string device_id = strip(printer_id, kDevicePrefix).value_or(std::string());
324	    if (const auto name = strip(printer_id, kNamedPrefix))
325	        for (const Printers::NamedPrinter& named : Printers::named_printers())
326	            if (named.name == *name)
327	                device_id = named.device_id;
328	    if (device_id.empty())
329	        return; // the card changed under the click; the refreshed rail says so
330	    // Upstream's own path to the Monitor, as the device popup and the
331	    // multi-machine page use. Selecting the tab and the machine by hand
332	    // instead left Home on screen: jump_to_monitor also guards on the Monitor
333	    // panel existing and selects the machine inside it. Upstream may still
334	    // decline the switch -- it vetoes the Monitor tab when the network plugin
335	    // is missing -- and that refusal is upstream's to make.
336	    m_frame.jump_to_monitor(device_id);
337	}
