372	std::string OrcaHomeBackend::rename_printer(const std::string& printer_id, const std::string& new_name)
373	{
374	    Plater* plater = wxGetApp().plater();
375	    if (plater == nullptr)
376	        return gone();
377	    if (const auto name = strip(printer_id, kNamedPrefix))
378	        return utf8(Printers::rename_named_printer(*plater, m_spools, *name, new_name));
379	    // A device keeps its own name. Upstream's dialog, as the device list
380	    // opens it, validates and sends the new one.
381	    MachineObject* machine = my_machine(strip(printer_id, kDevicePrefix).value_or(std::string()));
382	    if (machine == nullptr)
383	        return gone();
384	    EditDevNameDialog dialog(plater);
385	    dialog.set_machine_obj(machine);
386	    dialog.ShowModal();
387	    return {};
