390	std::string OrcaHomeBackend::remove_printer(const std::string& printer_id)
391	{
392	    Plater* plater = wxGetApp().plater();
393	    if (plater == nullptr)
394	        return gone();
395	    if (const auto name = strip(printer_id, kNamedPrefix))
396	        return utf8(Printers::remove_named_printer(*plater, m_spools, *name));
397	    // Removing a device unbinds it from the account, through upstream's
398	    // dialog, which confirms and reports for itself, as the device list does.
399	    const std::string device_id = strip(printer_id, kDevicePrefix).value_or(std::string());
400	    MachineObject*    machine   = my_machine(device_id);
401	    if (machine == nullptr)
402	        return gone();
403	    UnBindMachineDialog dialog(plater);
404	    dialog.update_machine_info(machine);
405	    if (dialog.ShowModal() == wxID_OK)
406	        wxGetApp().getDeviceManager()->set_selected_machine("");
407	    return {};
408	}
