9	const char* to_string(ProjectStatusKind kind)
10	{
11	    switch (kind) {
12	    case ProjectStatusKind::Draft: return "draft";
13	    case ProjectStatusKind::Sliced: return "sliced";
14	    case ProjectStatusKind::Printing: return "printing";
15	    case ProjectStatusKind::Completed: return "completed";
16	    case ProjectStatusKind::Unknown: break;
17	    }
18	    return "unknown";
19	}
20	
21	const char* to_string(PrinterState state)
22	{
23	    switch (state) {
24	    case PrinterState::Printing: return "printing";
25	    case PrinterState::Offline: return "offline";
26	    case PrinterState::Idle: break;
27	    }
28	    return "idle";
29	}
30	
31	const char* to_string(PrinterKind kind)
32	{
33	    switch (kind) {
34	    case PrinterKind::Device: return "device";
35	    case PrinterKind::Named: break;
36	    }
37	    return "named";
38	}
