40	namespace {
41	
42	void set_if_present(json& target, const char* key, const std::string& value)
43	{
44	    if (!value.empty())
45	        target[key] = value;
46	}
47	
48	json project_json(const ProjectEntry& project)
49	{
50	    json out{
51	        {"id", project.id},
52	        {"name", project.name},
53	        {"path", project.path},
54	        {"status", json{{"kind", to_string(project.status_kind)}, {"text", project.status_text}}},
55	    };
56	    set_if_present(out, "thumbnailUrl", project.thumbnail_url);
57	    return out;
58	}
59	
60	json printer_json(const PrinterEntry& printer)
61	{
62	    json spools = json::array();
63	    for (const SpoolEntry& spool : printer.spools)
64	        spools.push_back(json{{"colour", spool.colour}});
65	
66	    json out{
67	        {"id", printer.id},
68	        {"name", printer.name},
69	        {"kind", to_string(printer.kind)},
70	        {"state", to_string(printer.state)},
71	        {"spools", std::move(spools)},
72	        {"canLaunchMonitor", printer.can_launch_monitor},
73	        {"canOpenSettings", printer.can_open_settings},
74	        {"canRename", printer.can_rename},
75	        {"canRemove", printer.can_remove},
76	    };
77	    set_if_present(out, "statusText", printer.status_text);
78	    set_if_present(out, "connectionText", printer.connection_text);
79	    set_if_present(out, "connectionAction", printer.connection_action);
80	    set_if_present(out, "nozzleText", printer.nozzle_text);
81	    set_if_present(out, "materialLabel", printer.material_label);
82	    // A bar belongs to a running job; a finished or idle printer sends none
83	    // rather than a zero-width one.
84	    if (printer.state == PrinterState::Printing && printer.progress_percent >= 0)
85	        out["progressPercent"] = printer.progress_percent;
86	    return out;
87	}
88	
89	} // namespace
90	
91	json state_payload(const Snapshot& snapshot)
92	{
93	    json projects = json::array();
94	    for (const ProjectEntry& project : snapshot.projects)
95	        projects.push_back(project_json(project));
96	
97	    json printers = json::array();
98	    for (const PrinterEntry& printer : snapshot.printers)
99	        printers.push_back(printer_json(printer));
100	
101	    return json{
102	        {"appearance", snapshot.dark ? "dark" : "light"},
103	        {"projects", std::move(projects)},
104	        {"printers", std::move(printers)},
105	        {"highlightPrinter", snapshot.highlight_printer},
106	    };
107	}
