5	// A printing printer opens into its job; other printers show their connection
6	// and a next action so an optional connection can be completed later.
7	// Giving both states the same green dot made them indistinguishable, so only
8	// a printing printer's dot is colored. Either way the header row ends in the
9	// printer's actions menu.
10	export function PrinterCard({
11	  printer,
12	  otherNames,
13	  actions,
14	  onLaunchMonitor,
15	  highlighted,
16	}: {
17	  printer: PrinterInfo;
18	  otherNames: string[];
19	  actions: PrinterActions;
20	  onLaunchMonitor: (id: string) => void;
21	  // The printer a receipt just named: the card's own CSS animation draws
22	  // attention to it once and ends on its own -- no timer either side manages.
23	  highlighted?: boolean;
24	}) {
25	  const printing = printer.state === 'printing';
26	  const name = (
27	    <span className="printer-name-row">
28	      <PrinterGlyph />
29	      <span className="printer-name">{printer.name}</span>
30	    </span>
31	  );
32	  // A LAN-only device offers none of the actions; a menu of disabled rows
33	  // would be a button that does nothing, so it has none.
34	  const hasActions = printer.canOpenSettings || printer.canRename || printer.canRemove;
35	  const end = (
36	    <span className="printer-head-end">
37	      <span className={printing ? 'status-dot printing' : 'status-dot'} aria-hidden="true" />
38	      {hasActions && <PrinterMenu printer={printer} otherNames={otherNames} actions={actions} />}
39	    </span>
40	  );
41	  const cardClass = (base: string) => (highlighted ? `${base} printer-card-added` : base);
42	  if (!printing) {
43	    return (
44	      <div className={cardClass('printer-card')}>
45	        <div className="printer-head">{name}{end}</div>
46	        {printer.connectionText && <div className="printer-detail">{printer.connectionText}</div>}
47	        {printer.canLaunchMonitor ? (
48	          <button type="button" className="button-secondary launch-monitor" onClick={() => onLaunchMonitor(printer.id)}>
49	            <MonitorGlyph />Launch monitor
50	          </button>
51	        ) : printer.connectionAction === 'reconnect' && actions.onConnect && (
52	          <button type="button" className="button-secondary launch-monitor" onClick={() => actions.onConnect?.(printer.id)}>Reconnect</button>
53	        )}
54	      </div>
55	    );
56	  }
57	  return (
58	    <div className={cardClass('printer-card')}>
59	      <div className="printer-head">
60	        {name}
61	        {end}
62	      </div>
63	      {printer.statusText && <div className="printer-job">{printer.statusText}</div>}
64	      {printer.progressPercent !== undefined && (
65	        <div
66	          className="printer-progress"
67	          role="progressbar"
68	          aria-valuenow={Math.round(printer.progressPercent)}
69	          aria-valuemin={0}
70	          aria-valuemax={100}
71	        >
72	          <span style={{ width: `${Math.max(0, Math.min(100, printer.progressPercent))}%` }} />
73	        </div>
74	      )}
75	      {printer.connectionText && <div className="printer-detail">{printer.connectionText}</div>}
76	      {printer.nozzleText && <div className="printer-detail">{printer.nozzleText}</div>}
77	      {printer.spools.length > 0 && (
78	        <div className="printer-spools">
79	          {printer.materialLabel && <span className="printer-material">{printer.materialLabel}</span>}
80	          {printer.spools.map((spool, index) => (
81	            // The border is what keeps a black spool visible on the dark card
82	            // and a white one on the light card.
83	            <span
84	              key={`${spool.colour}-${index}`}
85	              className="spool-swatch"
86	              style={{ background: spool.colour }}
87	            />
88	          ))}
89	        </div>
90	      )}
91	      {printer.canLaunchMonitor && (
92	        <button type="button" className="button-secondary launch-monitor" onClick={() => onLaunchMonitor(printer.id)}>
93	          <MonitorGlyph />
94	          Launch monitor
95	        </button>
96	      )}
97	    </div>
98	  );
