1	// Typed view of the jusprin-home-bridge protocol. The canonical shared source
2	// is resources/jusprin/home/protocol.json; the constants here are derived from
3	// it at build time so the page and the native host cannot silently disagree
4	// about the protocol name or version.
5	//
6	// The page owns its own chrome strings, as the Agent page does. The host sends
7	// data plus the few lines only it can phrase: a project's status text and a
8	// printer's connection and nozzle lines come from native code that already has
9	// the device facts and the translations.
10	
11	import protocolJson from '@resources/jusprin/home/protocol.json';
12	
13	export const PROTOCOL_NAME: string = protocolJson.name;
14	export const PROTOCOL_VERSION: number = protocolJson.version;
15	export const PAGE_CAPABILITIES: string[] = protocolJson.capabilities;
16	
17	export type PageMessageType =
18	  | 'hello'
19	  | 'state_request'
20	  | 'open_project'
21	  | 'new_project'
22	  | 'import_project'
23	  | 'launch_monitor'
24	  | 'add_printer'
25	  | 'connect_printer'
26	  | 'open_printer_settings'
27	  | 'rename_printer'
28	  | 'remove_printer';
29	
30	export type HostMessageType =
31	  | 'hello_ack'
32	  | 'hello_reject'
33	  | 'state'
34	  | 'projects'
35	  | 'printers'
36	  | 'appearance'
37	  | 'printer_error'
38	  | 'bridge_error';
39	
40	export type Appearance = 'light' | 'dark';
41	
42	// What a project card's status line means, separate from what it says. Only
43	// 'printing' earns a colored dot; every other state takes the plain line, so
44	// an idle project cannot be mistaken for a running one.
45	//
46	// 'unknown' is honest about the current state of the codebase: nothing records
47	// per-project slice state yet, so the host sends what it can derive (the
48	// recent-file modified time) under this kind. When a real store exists, the
49	// host starts sending the other kinds and this page needs no change.
50	export type ProjectStatusKind = 'unknown' | 'draft' | 'sliced' | 'printing' | 'completed';
51	
52	export interface ProjectStatus {
53	  kind: ProjectStatusKind;
54	  // Host-formatted and already translated; the page never composes it.
55	  text: string;
56	}
57	
58	export interface ProjectInfo {
59	  id: string;
60	  name: string;
61	  // Shown only as a tooltip: the card is titled by name.
62	  path: string;
63	  // A file: URL the host resolved from the .3mf thumbnail, absent when the
64	  // project carries none.
65	  thumbnailUrl?: string;
66	  status: ProjectStatus;
67	}
68	
69	export type PrinterState = 'idle' | 'printing' | 'offline';
70	
71	export interface SpoolInfo {
72	  // '#RRGGBB', from the fork-owned spool store.
73	  colour: string;
74	}
75	
76	// A named printer is one the person added and names in JusPrin: this page
77	// confirms its rename and removal. A device is a Bambu printer no named
78	// printer stands for: its rename and removal open Orca's own dialogs, which
79	// confirm for themselves.
80	export type PrinterKind = 'named' | 'device';
81	
82	export interface PrinterInfo {
83	  id: string;
84	  name: string;
85	  kind: PrinterKind;
86	  // The card menu's items; one the host sends as false is shown disabled.
87	  canOpenSettings: boolean;
88	  canRename: boolean;
89	  canRemove: boolean;
90	  state: PrinterState;
91	  // Host-formatted status line, e.g. "Printing · 43% · 2h left". Present
92	  // whenever the host has something to say about the current job.
93	  statusText?: string;
94	  // 0-100, present only while printing; drives the progress bar's width.
95	  progressPercent?: number;
96	  connectionText?: string;
97	  connectionAction?: 'reconnect';
98	  nozzleText?: string;
99	  materialLabel?: string;
100	  spools: SpoolInfo[];
101	  canLaunchMonitor: boolean;
102	}
103	
104	// A printer action the host understood but could not carry out, such as a
105	// name another profile already has. The message is translated.
106	export interface PrinterErrorPayload {
107	  id: string;
108	  message: string;
109	}
110	
111	
112	export interface StatePayload {
113	  appearance: Appearance;
114	  projects: ProjectInfo[];
115	  printers: PrinterInfo[];
116	  // A printer the conversation just added; empty for any other push.
117	  highlightPrinter?: string;
118	}
119	
120	export interface Envelope<T = unknown> {
121	  protocol: string;
122	  version: number;
