void OrcaHomeBackend::open_printer_page(const std::string& name)
{
    Plater*       plater  = wxGetApp().plater();
    PresetBundle& presets = *wxGetApp().preset_bundle;
    const Preset* preset  = presets.printers.find_preset(name, false, true);
    if (plater == nullptr || preset == nullptr || preset->config.opt_string("print_host").empty())
        return; // the card changed under the click; the refreshed rail says so
    // Orca's Device tab shows the selected printer's page, so the printer is
    // selected first, as picking it in Orca's own printer list does -- with
    // Orca's own question when the project has unsaved printer edits. The
    // button's label says what it opens for that reason.
    if (presets.printers.get_selected_preset_name() != name && !SetupCommands::select_printer_preset(*plater, name))
        return;
    if (presets.printers.get_selected_preset_name() != name || presets.use_bbl_device_tab())
        return; // the person kept the printer they had
    // Upstream's own Device tab for a print host: the web view, loaded from
    // the selected printer's address. Selecting the preset has already built
    // it; both calls are no-ops when it is in place.
    m_frame.show_device(false);
    m_frame.load_printer_url();
    m_frame.select_tab(size_t(MainFrame::tpMonitor));
}

