.status-dot.printing {
  background: var(--status-success);
}

/* A printer card's dot is its connection: reachable, or known and silent. A
   printer with nothing verified draws no dot at all. */
.status-dot.online,
.status-dot.connected {
  background: var(--status-success);
}

.status-dot.offline {
  background: var(--status-warning);
}

/* Read by a screen reader, not drawn. */
.visually-hidden {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip-path: inset(50%);
  white-space: nowrap;
}

.printer-job {
