// The catalogue's models, read once: the packaged profiles do not change while
// the app runs. It names each model without its brand, which is how the card
// writes it.
const std::vector<PrinterSetup::CatalogPrinter>& catalog_models()
{
    const auto TMP_start = std::chrono::steady_clock::now();
    static const std::vector<PrinterSetup::CatalogPrinter> models =
        PrinterSetup::PrinterCatalog::load(Slic3r::resources_dir()).panel_printers();
    BOOST_LOG_TRIVIAL(warning) << "TMPTIMING catalog_models "
        << std::chrono::duration_cast<std::chrono::microseconds>(std::chrono::steady_clock::now() - TMP_start).count() << " us";
    return models;
}

// "X1 Carbon" for the profile's "Bambu Lab X1 Carbon". A model the catalogue
// does not list keeps the profile's own name.
std::string model_name(const std::string& printer_model)
{
    const auto& models = catalog_models();
    const auto  found  = std::find_if(models.begin(), models.end(),
                                      [&](const PrinterSetup::CatalogPrinter& model) { return model.model_id == printer_model; });
    return found == models.end() ? printer_model : found->model_name;
}

// The same for a device, which reports its model by its own id ("N1").
std::string device_model_name(const std::string& device_model_id)
{
    const auto& models = catalog_models();
    const auto  found  = std::find_if(models.begin(), models.end(), [&](const PrinterSetup::CatalogPrinter& model) {
        return !device_model_id.empty() && model.device_model_id == device_model_id;
    });
    return found == models.end() ? std::string() : found->model_name;
}

