async function homePage() {
  const targets = await (await fetch(`http://127.0.0.1:${PORT}/json/list`)).json();
  const page = targets.find((t) => t.type === 'page' && /jusprin[\\/]home[\\/]index\.html/.test(decodeURIComponent(t.url)));
  if (!page) throw new Error('no Home page among ' + targets.map((t) => t.url).join(', '));
  const socket = new WebSocket(page.webSocketDebuggerUrl);
  await new Promise((r) => socket.addEventListener('open', r));
  let next = 0;
  const call = (method, params = {}) => new Promise((resolve, reject) => {
    const id = ++next;
    const listener = (event) => {
      const m = JSON.parse(event.data);
      if (m.id !== id) return;
      socket.removeEventListener('message', listener);
      m.error ? reject(new Error(JSON.stringify(m.error))) : resolve(m.result);
    };
    socket.addEventListener('message', listener);
    socket.send(JSON.stringify({ id, method, params }));
  });
  const evaluate = async (expression) =>
    (await call('Runtime.evaluate', { expression, awaitPromise: true, returnByValue: true })).result.value;
  return { call, evaluate, close: () => socket.close() };
