// "Open printer page" on a print host's card: the printer becomes the
// selected one, as Orca's Device tab shows the selected printer's page, and
// that tab opens on the web view, which asks the saved address for it.
void verify_open_printer_page(const StandInHost& host)
{
    using namespace std::chrono_literals;
    const std::string selected_before = selected_printer();
    const int         tab_before      = m_notebook->GetSelection();
    check(selected_before != kAddedPrinter, "printer_page_fixture_starts_on_another_printer");
    Home::OrcaHomeBackend home(*m_frame, nullptr);
    home.launch_monitor(std::string("named:") + kAddedPrinter);
    check(selected_printer() == kAddedPrinter, "printer_page_selects_the_hosts_printer");
    auto* page = dynamic_cast<PrinterWebView*>(m_frame->m_tabpanel->GetPage(MainFrame::tpMonitor));
    check(m_frame->is_printer_view() && page != nullptr, "printer_page_opens_the_device_tabs_web_view");
    // The tab's browser is asked for the saved address, not whichever
    // page it last showed.
    wxWebView* browser = nullptr;
    if (page != nullptr)
        for (wxWindow* child : page->GetChildren())
            if (auto* found = dynamic_cast<wxWebView*>(child))
                browser = found;
    const std::string address = host.address();
    check(browser != nullptr && wait_for([browser, &address] {
              return browser->GetCurrentURL().ToStdString().rfind(address, 0) == 0;
          }, 20s),
          "printer_page_loads_the_saved_address");
    SetupCommands::select_printer_preset(*m_plater, selected_before);
    m_frame->select_tab(size_t(tab_before));
    check(selected_printer() == selected_before && m_notebook->GetSelection() == tab_before,
          "printer_page_fixture_restores_the_printer_and_page");
}

