param([int]$ProcessId, [string]$Out, [string]$Title = "", [switch]$Screen)
# Captures one of a process's top-level windows -- the one titled $Title, or
# else the largest -- from the screen, falling back to PrintWindow when there
# is no input desktop (a disconnected RDP session; GL content and modal
# dialogs are then missing). -Screen captures the whole primary screen.
# Never moves, resizes or maximises anything.
Add-Type -AssemblyName System.Drawing
Add-Type -AssemblyName System.Windows.Forms
Add-Type @"
using System;
using System.Collections.Generic;
using System.Text;
using System.Runtime.InteropServices;
public static class Win {
  [StructLayout(LayoutKind.Sequential)] public struct RECT { public int Left, Top, Right, Bottom; }
  public delegate bool EnumProc(IntPtr h, IntPtr p);
  [DllImport("user32.dll")] public static extern bool EnumWindows(EnumProc f, IntPtr p);
  [DllImport("user32.dll")] public static extern uint GetWindowThreadProcessId(IntPtr h, out uint pid);
  [DllImport("user32.dll")] public static extern bool IsWindowVisible(IntPtr h);
  [DllImport("user32.dll", CharSet=CharSet.Unicode)] public static extern int GetWindowTextW(IntPtr h, StringBuilder s, int n);
  [DllImport("user32.dll")] public static extern bool GetWindowRect(IntPtr h, out RECT r);
  [DllImport("user32.dll")] public static extern bool SetProcessDPIAware();
  [DllImport("user32.dll")] public static extern bool PrintWindow(IntPtr h, IntPtr dc, uint flags);
  public static List<IntPtr> Of(uint pid) {
    var found = new List<IntPtr>();
    EnumWindows((h, p) => { uint owner; GetWindowThreadProcessId(h, out owner);
      if (owner == pid && IsWindowVisible(h)) found.Add(h); return true; }, IntPtr.Zero);
    return found;
  }
  public static string Text(IntPtr h) { var s = new StringBuilder(512); GetWindowTextW(h, s, 512); return s.ToString(); }
}
"@
[Win]::SetProcessDPIAware() | Out-Null
if ($Screen) {
  $b = [System.Windows.Forms.Screen]::PrimaryScreen.Bounds
  $bmp = New-Object System.Drawing.Bitmap $b.Width, $b.Height
  $g = [System.Drawing.Graphics]::FromImage($bmp)
  $g.CopyFromScreen($b.Left, $b.Top, 0, 0, $bmp.Size)
  $bmp.Save($Out, [System.Drawing.Imaging.ImageFormat]::Png)
  "$Out $($b.Width)x$($b.Height) screen"; exit
}
$best = [IntPtr]::Zero; $area = 0
foreach ($h in [Win]::Of([uint32]$ProcessId)) {
  $r = New-Object Win+RECT; [Win]::GetWindowRect($h, [ref]$r) | Out-Null
  $a = ($r.Right - $r.Left) * ($r.Bottom - $r.Top)
  if ($Title) { if ([Win]::Text($h) -eq $Title) { $best = $h; break } }
  elseif ($a -gt $area -and [Win]::Text($h) -ne "") { $best = $h; $area = $a }
}
if ($best -eq [IntPtr]::Zero) { "no window titled '$Title'"; exit 1 }
$r = New-Object Win+RECT; [Win]::GetWindowRect($best, [ref]$r) | Out-Null
$w = $r.Right - $r.Left; $h = $r.Bottom - $r.Top
$bmp = New-Object System.Drawing.Bitmap $w, $h
$g = [System.Drawing.Graphics]::FromImage($bmp)
$how = "screen"
try { $g.CopyFromScreen($r.Left, $r.Top, 0, 0, $bmp.Size) } catch {
  $dc = $g.GetHdc(); [Win]::PrintWindow($best, $dc, 2) | Out-Null; $g.ReleaseHdc($dc); $how = "PrintWindow"
}
$bmp.Save($Out, [System.Drawing.Imaging.ImageFormat]::Png)
"$Out ${w}x${h} '$([Win]::Text($best))' via $how"
EOF
